// Tür davranış bilgisi: yüzgeç ısırma, karides ve salyangoz avı, küçük balık avı, aynı tür saldırganlığı.
// Her kayıt yalnızca açıkça okunmuş bir kaynak sayfasına dayanır (Seriously Fish, Fishkeeper, Practical Fishkeeping, OATA).
// Kaynakların çeliştiği kayıtlar `conflict` olarak tutulur ve kesin uyarı üretmez. Kaynak bulunamayan türler için kayıt yoktur;
// kayıt olmaması "sorun yok" anlamına gelmez. Araştırma 2026-09-28; bkz. docs/DECISIONS/0010-davranis-uyarilari.md.
// `condition` kullanıcıya gösterilebilir; `evidence` araştırma notudur (kısaltmalar: PFK = Practical Fishkeeping, FK = Fishkeeper, SF = Seriously Fish).
// "Karides yer" kayıtlarının kapsamı (`smallShrimpOnly`: kaynak riski küçük karidesle ya da yavruyla sınırlıyor) 2026-11-12'de kaynak sayfaları
// yeniden okunarak eklendi; işaretsiz kayıt bütün karideslerde uyarır (motor 1.16.0, docs/DECISIONS/0041-karides-tuzluluk-ve-baliksiz-dongu.md).

// `peaceful` (motor 1.18.0, docs/DECISIONS/0043-eksik-degerlendirme-ve-hukum-kurallari.md): kaynak türü açıkça barışçıl ya da topluluk akvaryumuna
// uygun sayıyor. Uyarı üretmez; motor türü yalnız "davranışı biliniyor" sayar ve "Değerlendirilemeyenler" kartına yazmaz.
// `peaceful` kaydında `condition` yoktur (ekranda gösterilmez); `evidence` kaynağın alıntısıdır.

// Veri sprinti E2 (2026-11-14, docs/CATALOG_LOG.md): iki bağımsız okuma karşılaştırıldı; risk kayıtları kaynak sayfası yeniden açılıp alıntı
// doğrulanarak eklendi. Kaynak listesi docs/DATA_SOURCES.md'deki kabul edilen kaynaklarla genişledi: Fishipedia, wirbellose.de (omurgasızlar), ScotCat.
export type BehaviorFlag = "finNipper" | "finNipTarget" | "eatsShrimp" | "shrimpSafe" | "eatsSnails" | "eatsSmallFish" | "notPiscivorous" | "conspecificAggression" | "peaceful";

export interface BehaviorRecord {
  flag: BehaviorFlag;
  /** Yalnızca conspecificAggression için: erkekler kavga eder ya da tür tek tutulmalıdır. */
  value?: "males" | "all";
  confidence: "explicit" | "conflict";
  condition?: string;
  evidence: string;
  source: "Seriously Fish" | "Fishkeeper" | "Practical Fishkeeping" | "OATA" | "Fishipedia" | "wirbellose.de" | "ScotCat";
  sourceUrl: string;
  additionalSourceUrls?: string[];
  /** Yalnızca notPiscivorous: kaynağın açıkça verdiği en büyük av boyu (cm); bu boy ve altındaki balıklar yine avlanabilir. Kaynak sayı vermiyorsa (ör. "birkaç milimetre") alan yoktur. */
  maxPreyCm?: number;
  /**
   * Yalnızca eatsShrimp (karar 0041): kaynak riski küçük (cüce) karidesle ya da yavruyla sınırlıyor ya da daha büyük bir karidesi (ör. Amano)
   * uygun arkadaş diye öneriyor; uyarı yalnız 4 cm ve altı karideste çıkar. Kaynak boy sınırı vermiyorsa alan yoktur ve uyarı bütün karideslerde çıkar.
   */
  smallShrimpOnly?: true;
  verifiedAt: string;
}

