  "dwarf-neon-rainbow": [{"flag":"peaceful","confidence":"explicit","evidence":"SF: 'Very peaceful and suitable for many community aquaria'","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/melanotaenia-praecox/","verifiedAt":"2026-11-14"}],
  "electric-blue-crayfish": [{"flag":"eatsShrimp","confidence":"explicit","condition":"Fishipedia diğer kabuklulara saldırdığını yazar; wirbellose.de'ye göre yetişkin cüce karideslerle genelde sorun çıkmaz, yavru karidesler yenir.","evidence":"Fishipedia (FR): 'elle s'attaquera aux autres crustacés et aux poissons'. wirbellose.de: yetişkinlerin cüce karideslerle birlikte tutulması genelde sorun çıkarmaz, yavru karidesler yem olarak görülür.","source":"Fishipedia","sourceUrl":"https://www.fishipedia.fr/fr/crustacea/procambarus-alleni","additionalSourceUrls":["https://www.wirbellose.de/artendatenbank/procambarus-alleni-sp-blau-florida-krebs/"],"verifiedAt":"2026-11-14"},{"flag":"eatsSmallFish","confidence":"explicit","condition":"Balıkları aktif avlamaz ama fırsat bulunca yakalar; Fishipedia ayrı akvaryum önerir.","evidence":"Fishipedia (FR): 'Nous conseillons une maintenance en aquarium spécifique car elle s'attaquera aux autres crustacés et aux poissons.' wirbellose.de: 'Stellen Fischen nicht aktiv nach, wenn sich aber die Gelegenheit bietet, fällt mal ein Fisch aus.'","source":"Fishipedia","sourceUrl":"https://www.fishipedia.fr/fr/crustacea/procambarus-alleni","additionalSourceUrls":["https://www.wirbellose.de/artendatenbank/procambarus-alleni-sp-blau-florida-krebs/"],"verifiedAt":"2026-11-14"},{"flag":"conspecificAggression","value":"all","confidence":"explicit","condition":"Fishipedia: erkekler çok kavgacı, çok büyük akvaryum dışında tek birey. wirbellose.de 100 × 40 cm akvaryuma 3–4 çift yazar.","evidence":"Fishipedia (FR): 'Les mâles sont particulièrement combatifs, il est recommandé de n'avoir qu'un individu par population excepté si l'aquarium est de taille très importante.' wirbellose.de: '3-4 Paare für ein 100x40cm Becken'.","source":"Fishipedia","sourceUrl":"https://www.fishipedia.fr/fr/crustacea/procambarus-alleni","additionalSourceUrls":["https://www.wirbellose.de/artendatenbank/procambarus-alleni-sp-blau-florida-krebs/"],"verifiedAt":"2026-11-14"}],
  "electric-blue-hap": [{"flag":"conspecificAggression","value":"males","confidence":"explicit","condition":"Çok büyük tank hariç.","evidence":"Tank çok büyük değilse yalnızca bir erkek; erkek başına birkaç dişi.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/sciaenochromis-fryeri/","verifiedAt":"2026-09-28"}],
  "elephantnose-fish": [{"flag":"conspecificAggression","value":"all","confidence":"explicit","condition":"Birden fazla için büyük, bol saklanaklı tank ve en az 5 birey.","evidence":"Hemcinsleriyle zor geçinir; yalnızca iki tane almak önerilmez, güçlü olan zayıfı ölümüne hırpalayabilir.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/gnathonemus-petersii/","verifiedAt":"2026-09-28"}],
  "elongatus-mpanga": [{"flag":"conspecificAggression","value":"males","confidence":"explicit","condition":"Erkek başına en az 4–6 dişi.","evidence":"Kendi türüne inanılmaz saldırgan; birden fazla erkek için çok büyük tank gerekir ve alttaki erkekler yine de öldürülebilir.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/pseudotropheus-elongatus/","verifiedAt":"2026-09-28"}],
