  "goldfish": [{"flag":"finNipper","confidence":"explicit","condition":"Yalnızca tek kuyruklu/hızlı formlar (common, comet), yavaş süslü formlara karşı; kaynak \"bazı bildirimler\" diyor","evidence":"Kaynak hızlı yüzen standart (tek kuyruklu) japon balıklarının bazı durumlarda süslü formların yüzgeçlerini ısırdığına dair bildirimler olduğunu belirtiyor ve ikisinin birlikte tutulmamasını öneriyor.","source":"OATA","sourceUrl":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-coldwater-fish/how-to-look-after-fancy-goldfish/","verifiedAt":"2026-09-28"},{"flag":"finNipTarget","confidence":"explicit","condition":"Yalnızca süslü, uzun yüzgeçli ve yavaş formlar (Oranda, Ryukin, Black Moor, Teleskop vb.)","evidence":"Kaynak bazı durumlarda hızlı standart japon balıklarının süslü formların yüzgeçlerini ısırdığını bildiriyor; PFK de japon balığı arkadaşlarının yüzgeç ısırmayan türlerden seçilmesi gerektiğini söylüyor.","source":"OATA","sourceUrl":"https://ornamentalfish.org/what-we-do/advice-information/care-sheets/caresheets-coldwater-fish/how-to-look-after-fancy-goldfish/","verifiedAt":"2026-09-28"},{"flag":"eatsShrimp","confidence":"explicit","evidence":"PFK (Nathan Hill), japon balığını karideslerle tutulmaması gereken balıklar arasında sayar; bu balıklarda karidesin yenip yenmeyeceği değil ne zaman yeneceği sorusu vardır.","source":"Practical Fishkeeping","sourceUrl":"https://www.practicalfishkeeping.co.uk/features/what-can-i-keep-with-shrimp/","verifiedAt":"2026-09-28"},{"flag":"eatsSnails","confidence":"explicit","condition":"Büyük bireyler.","evidence":"PFK (Jeremy Gay), büyük japon balıklarının Physa salyangozlarını iyi avladığını yazar.","source":"Practical Fishkeeping","sourceUrl":"https://www.practicalfishkeeping.co.uk/features/problem-solver-snails/","verifiedAt":"2026-09-28"},{"flag":"eatsSmallFish","confidence":"explicit","condition":"Yetişkin Japon balığı; White Cloud (yaklaşık 4 cm) boyundaki balıklar risk altında.","evidence":"White Cloud minnow’ları çok küçük Japon balıklarıyla tutulabilir, ancak olgun Japon balıkları bu minnow’ları yiyebilir.","source":"Practical Fishkeeping","sourceUrl":"https://www.practicalfishkeeping.co.uk/features/frequently-asked-questions-on-goldfish/","verifiedAt":"2026-09-28"}],
