  "pygmy-cory": [{"flag":"shrimpSafe","confidence":"explicit","condition":"Yetişkin karideslerle uyumlu; yavru karides kaybı olabilir (Practical Fishkeeping, cins düzeyinde).","evidence":"Seriously Fish, türü tek başına ya da çok küçük türlerle, belki bazı küçük tatlı su karidesleriyle tutmayı önerir. Fishkeeper da Red Crystal veya Cherry gibi küçük süs karideslerini uygun akvaryum arkadaşları arasında sayar. PFK (Nathan Hill) Corydoras'ları 'belki' grubunda sayar (yavruları büyük olasılıkla yer).","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/corydoras-pygmaeus/","additionalSourceUrls":["https://www.fishkeeper.co.uk/fish/freshwater/catfish/pygmy-cory","https://www.practicalfishkeeping.co.uk/features/what-can-i-keep-with-shrimp/"],"verifiedAt":"2026-09-28"},{"flag":"peaceful","confidence":"explicit","evidence":"SF: 'It's very peaceful, but doesn't make an ideal community fish'","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/gastrodermus-pygmaeus","verifiedAt":"2026-11-14"}],
  "rabauts-cory": [{"flag":"peaceful","confidence":"explicit","evidence":"SF: 'Peaceful and gregarious.'","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/corydoras-rabauti/","verifiedAt":"2026-11-14"}],
  "rabbit-snail": [{"flag":"peaceful","confidence":"explicit","evidence":"FK: 'great for peaceful community tanks containing small warm-water species of fish and shrimp'","source":"Fishkeeper","sourceUrl":"https://www.fishkeeper.co.uk/fish/freshwater/miscellaneous/sulawesi-snail","verifiedAt":"2026-11-14"}],
  "rainbow-shark": [{"flag":"conspecificAggression","value":"all","confidence":"explicit","condition":"Çok büyük, bol saklanaklı akvaryumda birlikte yaşatma denenebilir (birey başına en az 1 m çaplı bölge). Fishkeeper: tek ya da saldırganlığı dağıtan kalabalık grup.","evidence":"Yaşlandıkça yalnız yaşam içgüdüsü güçlenir; çoğu durumda tek tutulması önerilir.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/epalzeorhynchos-frenatum/","verifiedAt":"2026-09-28"}],
  "rainbow-snakehead": [{"flag":"eatsShrimp","confidence":"explicit","condition":"Canlı nehir karidesi yem olarak önerilir; cüce karidesler doğrudan av riski altındadır.","evidence":"Seriously Fish, yetişkinlere verilecek yemler arasında canlı nehir karidesini sayar; tür karidesi canlı av olarak yer.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/channa-bleheri/","verifiedAt":"2026-09-28"},{"flag":"conspecificAggression","value":"all","confidence":"explicit","condition":"Gençken grup; olgunlukta yalnız çift. Bireyler arasında fark olabilir.","evidence":"Gençler birlikte tutulabilir ama eşeysel olgunlukta birbirine saldırır; oluşan çift diğer hemcinslere düşmandır.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/channa-bleheri/","verifiedAt":"2026-09-28"}],
  "red-bellied-pacu": [{"flag":"finNipper","confidence":"explicit","condition":"Dar alanda yetişkinler","evidence":"Kaynak yetişkinlerin dar alanda hem kendi türünü hem diğer türleri kovalayıp yüzgeçlerini ısırarak baş belası olabileceğini belirtiyor.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/piaractus-brachypomus/","verifiedAt":"2026-09-28"}],
