  "red-clawed-crayfish": [{"flag":"conspecificAggression","value":"all","confidence":"explicit","condition":"Dar alanda kavga eder; uzuv kaybı sık görülür.","evidence":"FK: 'In cramped quarters, these territorial bottom-dwellers will fight, with loss of limb being all too common and so easily avoidable.'","source":"Fishkeeper","sourceUrl":"https://www.fishkeeper.co.uk/fish/freshwater/miscellaneous/red-clawed-crayfish","verifiedAt":"2026-11-14"}],
  "red-empress": [{"flag":"eatsSmallFish","confidence":"explicit","condition":"Ağzına sığan küçük balıklar.","evidence":"FK: 'Tankmates must be chosen with care as smaller fish will be eaten.' SF mizacı 'peaceful' diyor; asıl avcı değil.","source":"Fishkeeper","sourceUrl":"https://www.fishkeeper.co.uk/fish/freshwater/cichlids/red-empress-hap","verifiedAt":"2026-11-12"},{"flag":"conspecificAggression","value":"males","confidence":"explicit","condition":"Çok büyük akvaryum dışında tek erkek.","evidence":"SF: 'Males are very territorial and a very large tank would be required to keep more than one.'","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/protomelas-taeniolatus/","verifiedAt":"2026-11-12"}],
  "red-eye-tetra": [{"flag":"finNipper","confidence":"explicit","condition":"6-8 bireyden küçük grupta belirgin","evidence":"Kaynak türün biraz yüzgeç ısırıcı olarak ün yaptığını, bunun en az 6-8 bireylik sürüyle genellikle giderildiğini belirtiyor. PFK de kırmızı gözlü tetrayı diğer balıkların yüzgeçlerini ısırabilen türler arasında sayıyor.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/bario-sanctaefilomenae/","verifiedAt":"2026-09-28"}],
  "red-eyed-puffer": [{"flag":"finNipper","confidence":"explicit","evidence":"Kaynak türün özellikle küçük akvaryumlarda tank arkadaşlarının yüzgeçlerini ısırma eğilimi nedeniyle genel topluluğa uygun olmadığını ve tek tutulmasının en iyisi olduğunu belirtiyor. Fishkeeper da diğer balıkların yüzgeç ve bedenlerini ısırıp ciddi zarar verebileceğini söylüyor.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/carinotetraodon-lorteti/","verifiedAt":"2026-09-28"},{"flag":"eatsSnails","confidence":"explicit","evidence":"Seriously Fish, dişleri için salyangoz gibi kabuklu omurgasızların düzenli verilmesini önerir; Fishkeeper türü salyangoz yiyen balık olarak tanımlar.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/carinotetraodon-lorteti/","additionalSourceUrls":["https://www.fishkeeper.co.uk/fish/freshwater/miscellaneous/red-eyed-puffer"],"verifiedAt":"2026-09-28"},{"flag":"conspecificAggression","value":"all","confidence":"explicit","condition":"En iyisi tek tutmak; grup ancak yeterli alan ve uygun düzenle.","evidence":"SF: 'It tends to bite the fins of tankmates and is territorially aggressive, so is best kept alone, though a group can be kept with enough space and a suitable layout.'","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/carinotetraodon-lorteti/","verifiedAt":"2026-11-14"}],
