  "threadfin-acara": [{"flag":"finNipTarget","confidence":"explicit","evidence":"Kaynak özellikle saldırgan/bölgeci türlerden ve uzun yüzgeçleri ısırdığı bilinen türlerden kaçınılmasını belirtiyor. Fishkeeper da yüzgeç ısıran türlerden kaçınılmasını söylüyor.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/acarichthys-heckelii/","verifiedAt":"2026-09-28"},{"flag":"notPiscivorous","confidence":"explicit","condition":"Yaklaşık 2 cm ve altındaki balıklar ile yavrular için risk sürer.","evidence":"Genelde barışçıl; iki santimetre kadardan (kaynakta \"a couple of centimetres\") büyük hiçbir şeyi avlamaz.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/acarichthys-heckelii/","maxPreyCm":2,"verifiedAt":"2026-09-28"}],
  "threadfin-rainbowfish": [{"flag":"finNipTarget","confidence":"explicit","condition":"Özellikle olgun erkekler","evidence":"Kaynak olgun erkeklerin uzun yüzgeçlerinin bazı yaygın türlerce ısırılabileceğini, bu yüzden genel topluluğa uygun olmadığını belirtiyor. OATA ve Fishkeeper da yüzgeç ısırmayan barışçıl arkadaşlar öneriyor.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/iriatherina-werneri/","verifiedAt":"2026-09-28"},{"flag":"shrimpSafe","confidence":"explicit","evidence":"Seriously Fish, benzer boydaki küçük türlerin yanı sıra Caridina ve Neocaridina karideslerinin de uygun akvaryum arkadaşları olduğunu yazar.","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/iriatherina-werneri/","verifiedAt":"2026-09-28"},{"flag":"peaceful","confidence":"explicit","evidence":"SF: 'Very peaceful but not suitable for the general community aquarium'","source":"Seriously Fish","sourceUrl":"https://www.seriouslyfish.com/species/iriatherina-werneri","verifiedAt":"2026-11-14"}],
